def normalize_context(row):
    """Project legacy free-form context into a strict enum without inventing certainty."""
    explicit = row.get("context_requirement")
    legacy = row.get("context_required")
    value = fold_text(legacy).strip() if legacy is not None else ""
    if explicit in CONTEXT_REQUIREMENTS:
        requirement = explicit
    elif legacy is False or value in {"none", "nao", "nenhum", "nenhuma", "sem contexto", "nao precisa", "nao necessario"}:
        requirement = "none"
    elif legacy is True or value in {"required", "necessario", "obrigatorio"}:
        requirement = "required"
    elif value in {"helpful", "util", "ajuda"}:
        requirement = "helpful"
    elif value and value not in {"null", "none", "unresolved"}:
        requirement = "required"
    else:
        requirement = "unresolved"
    reason = row.get("context_reason")
    if reason is None and isinstance(legacy, str) and value not in {"", "null", *CONTEXT_REQUIREMENTS, "nao", "nenhum", "nenhuma"}:
        reason = legacy
    result = {"context_requirement": requirement,
              "context_reason": reason[:1500] if isinstance(reason, str) and reason.strip() else None,
              "context_required": None if requirement == "unresolved" else requirement,
              "legacy_context_required": legacy}
    for key in ("context_seconds_before", "context_seconds_after"):
        value = row.get(key)
        result[key] = float(value) if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and 0 <= value <= 3600 else (0.0 if requirement == "none" else None)
    return result


