def normalize_moment(moment):
    """Normalize control fields and preserve actual model/source provenance."""
    row = {**moment, **normalize_context(moment)}
    row.setdefault('reason', 'Justificativa nao fornecida pelo snapshot; revisar evidencia literal.')
    row.setdefault('categories', [])
    row.setdefault('complete_sentence', (row.get('text') or '').rstrip().endswith(('.', '?', '!')))
    if row.get("standalone_class") not in {"excellent", "good", "needs_context", "poor"}:
        row["standalone_class"] = "needs_context"
    row["needs_review"] = row.get("needs_review") if isinstance(row.get("needs_review"), bool) else True
    row["metadata_locale"] = "pt-BR"
    row["confidence_method"] = "subjective_llm_judgment" if row.get("method") == "ollama" else "lexical_heuristic"
    row["commercial_classification"] = classify_content(row.get("text", ""), row.get("evidence_segment_ids", []))
    row.update({key: row["commercial_classification"][key] for key in ("content_type", "commercial_score")})
    return row


