def topic_hierarchy(topics, segments):
    """Merge adjacent equivalent topics and keep the primary theme evidence-qualified."""
    by_id = {segment["segment_id"]: segment for segment in segments}
    merged = []
    merge_count = 0
    merge_decisions = []
    for original in topics:
        topic = {**original, **normalize_context(original), "metadata_locale": "pt-BR"}
        topic["merged_topic_ids"] = [topic["topic_id"]]
        ids = topic.get("evidence_segment_ids", [])
        literal = " ".join(by_id[segment_id].get("text", "") for segment_id in ids if segment_id in by_id)
        topic.update({key: value for key, value in classify_content(literal, ids).items() if key in ("content_type", "commercial_score")})
        previous = merged[-1] if merged else None
        lexical = terms(topic.get("topic", ""))
        before = terms(previous.get("topic", "")) if previous else set()
        label_similarity = len(lexical & before) / len(lexical | before) if lexical and before else 0.
        current_terms = terms(literal)
        previous_literal = " ".join(by_id[segment_id].get('text', '') for segment_id in previous.get('evidence_segment_ids', []) if segment_id in by_id) if previous else ''
        previous_terms = terms(previous_literal)
        shared_fraction = len(current_terms & previous_terms) / max(1, min(len(current_terms), len(previous_terms)))
        speaker_continuity = bool(set(topic.get('speakers', [])) & set(previous.get('speakers', []))) if previous else False
        equivalent = label_similarity >= .8 or (label_similarity >= .5 and shared_fraction >= .5 and speaker_continuity)
        if previous:
            merge_decisions.append({'previous_topic_id': previous['topic_id'], 'topic_id': topic['topic_id'],
                                    'decision': 'merge' if equivalent and topic['start'] - previous['end'] <= 3 and previous['content_type'] == topic['content_type'] else 'keep_separate',
                                    'label_similarity': label_similarity, 'shared_grounded_term_fraction': shared_fraction,
                                    'speaker_continuity': speaker_continuity, 'method': 'lexical_and_grounded_continuity_not_embedding_similarity'})
        if previous and equivalent and topic["start"] - previous["end"] <= 3 and previous["content_type"] == topic["content_type"]:
            previous["end"] = topic["end"]
            previous["evidence_segment_ids"] = list(dict.fromkeys(previous["evidence_segment_ids"] + ids))
            previous["merged_topic_ids"].extend(topic["merged_topic_ids"])
            previous['speakers'] = sorted(set(previous.get('speakers', [])) | set(topic.get('speakers', [])))
            merge_count += 1
        else:
            merged.append(topic)
    sections=[]
    for topic in merged:
        topic['parent_episode_id'] = 'EPISODE'
        previous=sections[-1] if sections else None
        lexical=terms(topic.get('topic',''))
        preceding=terms(previous['title']) if previous else set()
        related=bool(lexical and preceding and len(lexical & preceding)/len(lexical | preceding)>=.35)
        if (previous and related and previous['content_type']==topic['content_type'] and
                topic['start']-previous['end']<=3 and topic['end']-previous['start']<=900):
            previous['end']=topic['end']
            previous['topic_ids'].append(topic['topic_id'])
            previous['evidence_segment_ids']=list(dict.fromkeys(previous['evidence_segment_ids']+topic.get('evidence_segment_ids',[])))
        else:
            sections.append({
                'section_id': f'SECTION_{len(sections):04}', 'start': topic['start'], 'end': topic['end'],
                'parent_episode_id': 'EPISODE', 'level': 'major_section',
                'title': topic['topic'], 'topic_ids': [topic['topic_id']],
                'evidence_segment_ids': list(topic.get('evidence_segment_ids', [])),
                'content_type': topic['content_type'], 'method': 'adjacent_topic_lexical_relatedness_grouping',
                'needs_review': True,
            })
        topic['parent_section_id'] = sections[-1]['section_id']
    qualified = [topic for topic in merged if topic.get("method") == "ollama" and topic["content_type"] not in COMMERCIAL_TYPES
                 and terms(topic.get("topic", "")) and topic.get("evidence_segment_ids")]
    qualified.sort(key=lambda topic: (-(topic["end"] - topic["start"]), topic["topic_id"]))
    primary = {key: qualified[0].get(key) for key in ("topic_id", "topic", "summary", "evidence_segment_ids", "method")} if qualified else None
    covered = {segment_id for topic in merged for segment_id in topic.get("evidence_segment_ids", [])}
    count = len(merged)
    quality = {"topic_count": count, "merged_topic_count": merge_count,
               "major_section_count": len(sections), "topic_merge_decisions": merge_decisions,
               "heuristic_topic_fraction": sum(topic.get("method") != "ollama" for topic in merged) / count if count else None,
               "LLM_topic_fraction": sum(topic.get("method") == "ollama" for topic in merged) / count if count else None,
               "uncovered_segment_fraction": len(set(by_id) - covered) / len(by_id) if by_id else None,
               "commercial_topic_fraction": sum(topic["content_type"] in COMMERCIAL_TYPES for topic in merged) / count if count else None,
               "primary_theme_status": "grounded_model_topic_requires_review" if primary else "unresolved_no_qualified_theme",
               "duplicate_topic_similarity_warnings": []}
    return merged, sections, primary, [topic["topic_id"] for topic in qualified[1:]], quality


