def _equivalent(left, right):
    """Require temporal and editorial equivalence for non-exact deduplication."""
    left_start, left_end = left["ideal_start"], left["ideal_end"]
    right_start, right_end = right["ideal_start"], right["ideal_end"]
    intersection = max(0.0, min(left_end, right_end) - max(left_start, right_start))
    if not intersection:
        return False, False
    exact = abs(left_start-right_start)<=1e-6 and abs(left_end-right_end)<=1e-6
    if exact:
        return True, True
    union = max(left_end, right_end) - min(left_start, right_start)
    shorter = min(left_end - left_start, right_end - right_start)
    overlap = intersection / shorter if shorter > 0 else 0.0
    left_ids, right_ids = set(left.get("evidence_segment_ids", [])), set(right.get("evidence_segment_ids", []))
    evidence_share = len(left_ids & right_ids) / max(1, min(len(left_ids), len(right_ids)))
    left_terms = terms(left.get("core_moment", {}).get("text") or left.get("text", ""))
    right_terms = terms(right.get("core_moment", {}).get("text") or right.get("text", ""))
    lexical_share = len(left_terms & right_terms) / max(1, len(left_terms | right_terms))
    return (intersection / union >= .8 or overlap >= .8) and (evidence_share >= .8 or lexical_share >= .85), False


